-- message.read (line 49): chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)}
CREATE OR REPLACE VIEW authz_int."message__read" AS
  SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__chat__read") x) k)
    AND coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false);

CREATE FUNCTION authz_gen."ms.members:insert:items"(p_row "ms"."members") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(((EXISTS (SELECT 1 FROM authz_gen."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__setup" v WHERE v.id = "members"."chat_id")
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."user__has_blocked" v WHERE v.id = "members"."user_id"), false))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__join" v WHERE v.id = "members"."chat_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('ms.members', 'insert')), false),
    coalesce(true, false),
    coalesce((EXISTS (SELECT 1 FROM authz_gen."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__setup" v WHERE v.id = "members"."chat_id")
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."user__has_blocked" v WHERE v.id = "members"."user_id"), false)), false),
    coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__add_members" v WHERE v.id = "members"."chat_id"), false),
    coalesce((coalesce((role = 'member'), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__setup" v WHERE v.id = "members"."chat_id")
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id"))), false),
    coalesce(NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."user__has_blocked" v WHERE v.id = "members"."user_id"), false), false),
    coalesce((coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__join" v WHERE v.id = "members"."chat_id")), false),
    coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__join" v WHERE v.id = "members"."chat_id"), false),
    coalesce(coalesce("members"."user_id" = (SELECT authz.uid()), false), false),
    coalesce(coalesce((role = 'member'), false), false)]
  FROM (SELECT (p_row).*) AS "members";
END;

CREATE OR REPLACE FUNCTION authz_gen."ms.members:insert:why"(p_row "ms"."members") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.members:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : (chat.add_members and ({role = ''member''} or chat.setup or (chat.manage and {role <> ''owner''})) and not person.has_blocked) or (chat.join and person and {role = ''member''})  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.members insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on ms.members'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || '(chat.add_members and ({role = ''member''} or chat.setup or (chat.manage and {role <> ''owner''})) and not person.has_blocked)';
  IF NOT v[4] THEN
    RETURN NEXT CASE WHEN v[5] THEN '    yes  ' ELSE '    no   ' END || 'chat.add_members';
  IF NOT v[5] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'add_members') l LIMIT 20;
    END LOOP;
  END IF;
    RETURN NEXT CASE WHEN v[6] THEN '    yes  ' ELSE '    no   ' END || '({role = ''member''} or chat.setup or (chat.manage and {role <> ''owner''}))';
    RETURN NEXT CASE WHEN v[7] THEN '    yes  ' ELSE '    no   ' END || 'not person.has_blocked';
  END IF;
  RETURN NEXT CASE WHEN v[8] THEN '  yes  ' ELSE '  no   ' END || '(chat.join and person and {role = ''member''})';
  IF NOT v[8] THEN
    RETURN NEXT CASE WHEN v[9] THEN '    yes  ' ELSE '    no   ' END || 'chat.join';
  IF NOT v[9] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'join') l LIMIT 20;
    END LOOP;
  END IF;
    RETURN NEXT CASE WHEN v[10] THEN '    yes  ' ELSE '    no   ' END || 'person';
    RETURN NEXT CASE WHEN v[11] THEN '    yes  ' ELSE '    no   ' END || '{role = ''member''}';
  END IF;
END $f$;

-- ms.members insert (line 83): (chat.add_members and ({role = 'member'} or chat.setup or (chat.manage and {role <> 'owner'})) and not person.has_blocked) or (chat.join and person and {role = 'member'})
CREATE POLICY "authz_insert" ON "ms"."members" FOR INSERT TO ms_app
  WITH CHECK (((SELECT authz_int.scope_cmd('ms.members', 'insert')) AND ((EXISTS (SELECT 1 FROM authz_gen."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__setup" v WHERE v.id = "members"."chat_id")
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."user__has_blocked" v WHERE v.id = "members"."user_id"), false))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__join" v WHERE v.id = "members"."chat_id"))))
    OR authz_gen."ms.members:insert:refuse"(ROW("members".*)::"ms"."members"));
COMMENT ON POLICY "authz_insert" ON "ms"."members" IS 'authzc';

-- ms.messages select (line 96): read
CREATE POLICY "authz_select" ON "ms"."messages" FOR SELECT TO ms_app
  USING (((SELECT authz_int.scope_cmd('ms.messages', 'select')) AND (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "messages"."chat_id"))));
COMMENT ON POLICY "authz_select" ON "ms"."messages" IS 'authzc';

CREATE OR REPLACE FUNCTION authz_gen."ms.members:column_7:why"(p_row "ms"."members") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.members:column_7:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update chat_id, user_id, joined_at, joined_seq : {false}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.members update chat_id, user_id, joined_at, joined_seq'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on ms.members'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || '{false}';
END $f$;

-- ms.members update chat_id, user_id, joined_at, joined_seq (line 92): {false}
-- checked on the row before the change, for roles that row-level security applies to
CREATE OR REPLACE FUNCTION authz_int."membership__update_7"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text;
BEGIN
  IF pg_catalog.row_security_active(TG_RELID)
     AND NOT coalesce((SELECT coalesce((false), false) FROM (SELECT OLD.*) AS "members"), false) THEN
    BEGIN
      v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.members:column_7:why"(OLD) l);
    EXCEPTION WHEN OTHERS THEN
      v_lines := 'no explanation: ' || SQLERRM;
    END;
    RAISE EXCEPTION 'changing chat_id, user_id, joined_at, joined_seq of ms.members % needs: {false}', ROW(OLD."chat_id"::bigint, OLD."user_id"::uuid)::text USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
      SCHEMA = 'ms', TABLE = 'members', CONSTRAINT = 'authz_update', HINT = 'rowfence help AZ709';
  END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER "authz_update_7" BEFORE UPDATE ON "ms"."members" FOR EACH ROW
  WHEN (OLD."chat_id" IS DISTINCT FROM NEW."chat_id"
     OR OLD."user_id" IS DISTINCT FROM NEW."user_id"
     OR OLD."joined_at" IS DISTINCT FROM NEW."joined_at"
     OR OLD."joined_seq" IS DISTINCT FROM NEW."joined_seq")
  EXECUTE FUNCTION authz_int."membership__update_7"();

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN coalesce((SELECT coalesce((id = (SELECT authz.uid())), false) FROM "ms"."users" o WHERE o."id" = v_uuid), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false)) FROM "ms"."bots" o WHERE o."id" = v_bigint), false);
        WHEN 'manage_keys' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false)) FROM "ms"."bots" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN coalesce((SELECT (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id")) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'post' THEN RETURN coalesce((SELECT ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id")) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'manage' THEN RETURN coalesce((SELECT (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'invite' THEN RETURN coalesce((SELECT (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'join' THEN RETURN coalesce((SELECT ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'setup' THEN RETURN coalesce((SELECT (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false)) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        WHEN 'add_members' THEN RETURN coalesce((SELECT ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false))) FROM "ms"."chats" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN coalesce((SELECT (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id")) FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq")), false);
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)) FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq")), false);
        WHEN 'remove' THEN RETURN coalesce((SELECT (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id")) FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((v_text)::authz_gen."message__key")."chat_id", ((v_text)::authz_gen."message__key")."seq")), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce((id = (SELECT authz.uid())), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce((id = (SELECT authz.uid())), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE o."id" > p_after::uuid AND coalesce((id = (SELECT authz.uid())), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'bot.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'bot.manage_keys' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.post' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.invite' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.join' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.setup' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.add_members' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'message.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    WHEN 'message.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    WHEN 'message.remove' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__read__why"(p_id text, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.read = chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)}';
  BEGIN
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__chat__read") x) k)
    AND coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__chat__read");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.read';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('chat', v_t.id) THEN
        RETURN NEXT pad || '  ' || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has read' ELSE ', without read' END;
      IF NOT ('chat:read:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_t.id::bigint, p_depth + 2 + 1, p_seen || ('chat:read:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{seq > coalesce(ms.joined_seq(chat_id), 0)}';
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."users" "users" WHERE "users"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('ms.users', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."bots" "bots" WHERE "bots"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.bots', 'select')) AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    AND coalesce((active), false)));
    WHEN 'chat' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chats" "chats" WHERE "chats"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."members" "members" WHERE ("members"."chat_id", "members"."user_id") = (((p_id)::authz_gen."membership__key")."chat_id", ((p_id)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('ms.members', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "members"."chat_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."messages" "messages" WHERE ("messages"."chat_id", "messages"."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq")
        AND (SELECT authz_int.scope_cmd('ms.messages', 'select')) AND (coalesce((seq > coalesce(ms.joined_seq(chat_id), 0)), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "messages"."chat_id")));
    WHEN 'chat_bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chat_bots" "chat_bots" WHERE ("chat_bots"."chat_id", "chat_bots"."bot_id") = (((p_id)::authz_gen."chat_bot__key")."chat_id", ((p_id)::authz_gen."chat_bot__key")."bot_id")
        AND (SELECT authz_int.scope_cmd('ms.chat_bots', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "chat_bots"."chat_id"));
    WHEN 'block' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."blocks" "blocks" WHERE ("blocks"."blocker_id", "blocks"."blocked_id") = (((p_id)::authz_gen."block__key")."blocker_id", ((p_id)::authz_gen."block__key")."blocked_id")
        AND (SELECT authz_int.scope_cmd('ms.blocks', 'select')) AND coalesce("blocks"."blocker_id" = (SELECT authz.uid()), false));
    ELSE RETURN false;
  END CASE;
END $f$;

-- authz_gen.policy_lines: its rows again
DELETE FROM authz_gen.policy_lines;
INSERT INTO authz_gen.policy_lines VALUES
  ('relation chat.bot', 'line 22'),
